import os, json, datetime as dt, sys
sys.path.append('storage/shared/atlas/tools')
import ci_validate

CUR = "storage/shared/atlas/edges/index.json"
AUTO= "storage/shared/atlas/edges/index_auto.json"

def load_idx(p):
    if not os.path.exists(p): return {"entries": [], "updated": None}
    try:
        with open(p,"r",encoding="utf-8") as f: return json.load(f)
    except Exception:
        return {"entries": [], "updated": None}

def norm(ents):
    out=[]
    for e in ents:
        if isinstance(e, dict) and "entry_path" in e: out.append({"entry_path": e["entry_path"]})
        elif isinstance(e, dict) and "path" in e:     out.append({"entry_path": e["path"]})
        elif isinstance(e, str):                      out.append({"entry_path": e})
    return out

cur = norm(load_idx(CUR).get("entries", []))
auto= norm(load_idx(AUTO).get("entries", []))
seen = {e["entry_path"]: e for e in auto}
for e in cur: seen[e["entry_path"]] = e
merged = sorted(seen.values(), key=lambda x: x["entry_path"])
os.makedirs(os.path.dirname(AUTO), exist_ok=True)
with open(AUTO,"w",encoding="utf-8") as f:
    json.dump({"entries": merged, "generated": dt.datetime.utcnow().isoformat()+"Z"}, f, ensure_ascii=False, indent=2)

out = ci_validate.run()
print(json.dumps({"status":"ok","auto_entries": len(merged), "ci_entries_found": out.get("entries_found"), "ci_ok": out.get("ok"), "ci_with_errors": out.get("with_errors")}))
